		parentId: '',
		type: I.BlockType.Text,
		childrenIds: [],
		hAlign: I.BlockHAlign.Left,
		vAlign: I.BlockVAlign.Top,
		bgColor: '',
		fields: {},
		content: { style: I.TextStyle.Paragraph },
		layout: I.ObjectLayout.Page,
		...overrides,
	} as I.Block);
};

